CREATE TABLE outbox_message (
  message_id uuid NOT NULL,
  destination text NOT NULL,
  message_type text NOT NULL,
  aggregate_id uuid NOT NULL,
  payload jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamp with time zone NOT NULL,
  delivered_at timestamp with time zone,
  attempts integer NOT NULL DEFAULT 0,
  last_error text,
  CONSTRAINT outbox_message_pkey PRIMARY KEY (message_id),
  CONSTRAINT outbox_message_attempts_check CHECK ((attempts >= 0)),
  CONSTRAINT outbox_message_check CHECK (((delivered_at IS NULL) OR (delivered_at >= created_at))),
  CONSTRAINT outbox_message_destination_check CHECK ((destination ~ '^[a-z]+(-[a-z]+)*(:[a-z0-9-]+)?$'::text)),
  CONSTRAINT outbox_message_message_type_check CHECK ((message_type ~ '^[a-z]+(-[a-z]+)*$'::text)),
  CONSTRAINT outbox_message_payload_check CHECK ((jsonb_typeof(payload) = 'object'::text))
);
CREATE INDEX outbox_message_undelivered ON outbox_message USING btree (destination, created_at) WHERE (delivered_at IS NULL);
